TITLE = "Atlassian + OpenAI Partnership: Rovo, Jira & Codex | SXF / AI"
DESCRIPTION = "Atlassian and OpenAI partnership explained: GPT-6 in Rovo, Jira and Confluence context for ChatGPT/Codex, MCP access, permissions and next steps."
INTRO = "Atlassian and OpenAI's October 6 partnership expansion connects frontier models to enterprise work: Rovo uses the Teamwork Graph, while ChatGPT and Codex can draw on Jira and Confluence context through supported Atlassian integrations. The bigger story is how organizations move from AI answers to governed, reviewable work—not an overnight launch of fully autonomous Jira agents."
CANONICAL = "https://sxf.si/signals/atlassian-and-openai-expand-partnership-to-turn-enterprise-knowledge-i-60ef2af/"
SOURCES = ["https://openai.com/index/atlassian-partnership","https://www.atlassian.com/blog/company-news/atlassian-openai-strategic-partnership","https://www.atlassian.com/partnerships/openai/guide","https://www.atlassian.com/blog/company-news/team26-europe-atlassian-mcp"]
FAQS = [["What did Atlassian and OpenAI announce on October 6, 2026?","The companies expanded a partnership that began in 2023. OpenAI frontier models will support experiences across Atlassian's platform and Rovo, while Atlassian enterprise context can be used with supported ChatGPT and Codex integrations."],["What does the partnership change in Rovo?","Atlassian can integrate evolving OpenAI models into Rovo while grounding their responses in its Teamwork Graph of projects, people, documents and decisions. This is intended to improve context-aware reasoning and actions."],["Can ChatGPT and Codex access Jira and Confluence?","Supported Atlassian MCP and plugin integrations let authorized ChatGPT and Codex users work with permitted Jira and Confluence context. Exact capabilities depend on the client, connected apps and administrator settings."],["What is Atlassian's Teamwork Graph?","It is Atlassian's enterprise context layer, connecting work items, documents, projects, people, decisions and relationships to give Rovo and connected AI systems better understanding of organizational work."],["Does the announcement mean AI agents can autonomously complete every Jira task now?","No. The companies describe further agent assignment, tracking, synchronized work and review features as areas of exploration or development. The October 2026 partnership should not be read as a universal availability promise."],["Which OpenAI models are part of the deal?","OpenAI says the expanded agreement includes access to frontier models such as GPT-6 Astra and the GPT-5.6 series. It does not say that every model is selectable in every Atlassian product or plan."],["How many Atlassian developers already use Codex?","OpenAI and Atlassian reported that more than 3,000 Atlassian developers use Codex in terminal, editor or code review workflows. This is Atlassian's own adoption figure, not a quantified productivity gain."],["How is Atlassian MCP different from the Teamwork Graph CLI?","Atlassian MCP exposes permitted Atlassian tools and context to supported AI clients via the Model Context Protocol. The Teamwork Graph CLI provides terminal-oriented access to the organization's connected work context; suitability depends on client and workflow."],["What should enterprises verify before enabling the integration?","Confirm product and plan eligibility, OAuth scopes, data permissions, administrator approval, permitted write actions, review and audit trails, data retention terms, and how success will be measured before broad deployment."],["How can teams measure business value?","Start with a controlled workflow such as launch-readiness reporting or ticket-to-code planning. Compare baseline versus assisted task completion time, accuracy of retrieved context, review effort and error rates; do not assume the partnership announcement proves ROI."]]
BODY = "\n        <section class=\"signal-deep-dive shell\" data-atlassian-openai-analysis aria-labelledby=\"atlassian-openai-deep-dive\">\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">SXF ORIGINAL ANALYSIS / ENTERPRISE AI</p><h2 id=\"atlassian-openai-deep-dive\">Atlassian and OpenAI: what changes for Rovo, Jira, Confluence and Codex?</h2></div><span>Analysis updated October 13, 2026</span></div>\n          <div class=\"deep-dive-lead\">\n            <p>The partnership expansion announced on <strong>October 6, 2026</strong> connects two things enterprises often struggle to bring together: capable AI reasoning and trustworthy knowledge of their own work. <strong>OpenAI supplies frontier models</strong>; <strong>Atlassian supplies work context</strong> through Jira, Confluence, Rovo and its Teamwork Graph. The practical ambition is not merely better summaries—it is helping users identify blockers, prepare plans and carry out supported tasks with human oversight.</p>\n            <p><strong>SXF's assessment:</strong> this is primarily a context-and-workflow integration story, not a new standalone AI model launch. Better context may make agents more useful, but measurable outcomes depend on current, accurate records, appropriate permissions and how well organizations govern automated actions. The announcement does not prove a specific accuracy or ROI improvement for every customer.</p>\n          </div>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">FAST ANSWERS</p><h2>What is announced, available, and still planned?</h2></div></div>\n          <div class=\"deep-dive-grid\">\n            <article><span>ANNOUNCED · EXPANDED PARTNERSHIP</span><h3>OpenAI frontier models across Atlassian.</h3><p>The agreement expands Atlassian's access to OpenAI models, including <strong>GPT-6 Astra and the GPT-5.6 series</strong>. Rovo can incorporate model improvements via OpenAI APIs. This does not establish a single model SKU, price or rollout schedule across all Rovo products.</p></article>\n            <article><span>AVAILABLE · CONNECTED CONTEXT</span><h3>ChatGPT and Codex can work with Atlassian knowledge.</h3><p>Atlassian describes MCP and plugin connections that bring permitted Jira work items, Confluence pages and related project context into supported ChatGPT and Codex workflows. Actual tools and access depend on a team's authorization and product eligibility.</p></article>\n            <article><span>ALREADY IN USE · INTERNAL ADOPTION</span><h3>Atlassian says 3,000+ developers use Codex.</h3><p>The company reports Codex adoption across terminals, IDEs and code review. This is evidence of internal deployment, not proof of a 3,000-developer productivity uplift or a universal enterprise rollout.</p></article>\n            <article><span>EXPLORATORY · DEEPER AGENT COORDINATION</span><h3>Agent assignment and progress inside Jira.</h3><p>Both partners discuss tighter workflows for assigning work to agents, tracking progress and reviewing results. Treat these future-oriented capabilities as plans until dedicated release notes confirm availability, permissions and scope.</p></article>\n          </div>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">HOW THE INTEGRATION WORKS</p><h2>Four layers: business context, reasoning, controlled action, review.</h2></div></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Enterprise context:</strong> Jira issues, Confluence documentation, people, projects and recorded decisions are connected by Atlassian's <strong>Teamwork Graph</strong>. Context changes as work changes, so freshness and access rights matter.</p></div>\n            <div><span>02</span><p><strong>AI reasoning:</strong> Rovo integrates OpenAI frontier reasoning, while supported ChatGPT and Codex clients can request Atlassian context via connectors and MCP. An AI answer is only as reliable as the information it receives.</p></div>\n            <div><span>03</span><p><strong>Action within scope:</strong> an authorized AI client may prepare or carry out supported operations depending on the tool, granted permission and product surface. It should not silently gain broader access than the user or administrator intended.</p></div>\n            <div><span>04</span><p><strong>Human ownership:</strong> engineers and managers verify evidence, approve sensitive actions and record decisions in normal systems of work. The companies explicitly discuss keeping humans in control as workflows deepen.</p></div>\n          </div>\n          <p>See the <a href=\"https://www.atlassian.com/partnerships/openai/guide\" target=\"_blank\" rel=\"noopener noreferrer\">Atlassian + OpenAI integration guide</a> for current connection paths and eligibility. For the underlying standard, SXF explains the <a href=\"/guides/model-context-protocol-mcp/\">Model Context Protocol (MCP)</a> and its trust boundaries.</p>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">REAL WORK EXAMPLE</p><h2>From a launch-readiness question to a verified delivery plan.</h2></div></div>\n          <div class=\"deep-dive-grid\">\n            <article><span>STEP 1 · ASK</span><h3>Is the product launch on track?</h3><p>A product manager asks Rovo to review current milestones and dependencies. The request is about the organization's actual plan, not general web knowledge.</p></article>\n            <article><span>STEP 2 · RETRIEVE</span><h3>Connect Jira blockers and Confluence decisions.</h3><p>The Teamwork Graph helps locate relevant tasks, documentation and responsible teams. A useful answer should show which records support each blocker or status claim.</p></article>\n            <article><span>STEP 3 · INTERPRET</span><h3>Identify risks and proposed next steps.</h3><p>OpenAI reasoning can organize retrieved evidence into a risk summary and proposed actions. The assistant should distinguish verified facts from inference or missing information.</p></article>\n            <article><span>STEP 4 · REVIEW</span><h3>Assign humans to check and act.</h3><p>The manager validates ownership and deadlines, approves any changes, and tracks follow-up in the source systems. This is a workflow illustration adapted from OpenAI's launch-readiness example, not a claim of an automated production result.</p></article>\n          </div>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">FOR DEVELOPERS</p><h2>Jira requirements → Codex planning → code review.</h2></div></div>\n          <p>A developer working on a feature can authorize a supported Atlassian connection, ask Codex to inspect the relevant Jira issue and linked architecture decision, then request a technical implementation plan. The key benefit is reducing manual copying of context between tools. The key risk is that <strong>stale tickets, incomplete specifications or excess connector permissions</strong> can propagate into code suggestions.</p>\n          <p><strong>Practical pilot:</strong> pick one repository and one low-risk Jira issue; confirm the linked Confluence decision is current; check what the connector can read and write; have Codex produce a plan or patch; then review tests, security and references before merging. This is a recommended test procedure, not a stated prerequisite of the partnership.</p>\n          <p>Atlassian's official guide distinguishes <strong>Atlassian MCP Server for ChatGPT</strong>, <strong>Atlassian MCP Server for Codex</strong>, <strong>Codex deep links</strong>, and <strong>OpenAI model selection in Rovo Agents</strong>. The exact setup varies by plan and client; use the <a href=\"https://www.atlassian.com/partnerships/openai/guide\" target=\"_blank\" rel=\"noopener noreferrer\">current integration documentation</a> rather than assuming a one-click integration for every team.</p>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">SECURITY AND GOVERNANCE</p><h2>Six checks that determine whether enterprise AI is ready for work.</h2></div></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Identity and scopes:</strong> inspect which user's Atlassian identity is connected and which OAuth/MCP scopes are granted. Do not treat a successful sign-in as approval to expose every company record.</p></div>\n            <div><span>02</span><p><strong>Read versus write:</strong> define which actions can be proposed, executed or require explicit human approval, especially changing Jira workflows, creating tickets or posting confidential material.</p></div>\n            <div><span>03</span><p><strong>Freshness and provenance:</strong> verify that retrieved decisions and project states are current. Prefer linked Jira and Confluence evidence to confidently phrased but untraceable summaries.</p></div>\n            <div><span>04</span><p><strong>Data handling:</strong> check tenant configuration, applicable retention terms, connected products and organizational controls before routing sensitive documents into any external AI client.</p></div>\n            <div><span>05</span><p><strong>Measurement:</strong> record baseline task time, review load, correction rate and output quality. Atlassian mentions DX for measuring engineering impact; the announcement does not supply a universal productivity percentage.</p></div>\n            <div><span>06</span><p><strong>Availability:</strong> verify plan eligibility, region, enabled connectors and product release status. Do not confuse currently supported MCP access with future autonomous-agent orchestration.</p></div>\n          </div>\n          <p>For a detailed permission model, read SXF's <a href=\"/guides/ai-agent-authorization/\">AI agent authorization guide</a>. For deployment economics and evaluation, see <a href=\"/guides/ai-agent-cost/\">enterprise AI agent cost and ROI</a>.</p>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">THE BIGGER IMPLICATION</p><h2>Why enterprise context may matter more than another model upgrade.</h2></div></div>\n          <p>A frontier model can reason about a generic migration plan. What makes it helpful to a real team is knowing <em>which service is being migrated, what Jira says is blocked, where the Confluence architecture decision lives and who can approve the change</em>. Atlassian's Teamwork Graph attempts to make those connections available to authorized AI workflows. That is why this announcement matters beyond the names of the model versions.</p>\n          <p>The risk is equally specific: incomplete context can produce precise-looking recommendations that are wrong for the organization's latest decision. Strong deployments connect outputs back to source records, restrict actions to authorized capabilities and require review at meaningful checkpoints. The partnership provides building blocks; implementation quality determines results.</p>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">PRIMARY SOURCES AND RELATED RESEARCH</p><h2>Read official product guidance and SXF context.</h2></div></div>\n          <div class=\"model-related-links\">\n            <a href=\"https://openai.com/index/atlassian-partnership\" target=\"_blank\" rel=\"noopener noreferrer\"><span>ORIGINAL ANNOUNCEMENT</span><strong>OpenAI — Atlassian partnership</strong><b>↗</b></a>\n            <a href=\"https://www.atlassian.com/blog/company-news/atlassian-openai-strategic-partnership\" target=\"_blank\" rel=\"noopener noreferrer\"><span>AT LASSIAN'S PERSPECTIVE</span><strong>Enterprise context and roadmap</strong><b>↗</b></a>\n            <a href=\"https://www.atlassian.com/partnerships/openai/guide\" target=\"_blank\" rel=\"noopener noreferrer\"><span>SETUP AND ELIGIBILITY</span><strong>ChatGPT, Codex, Jira and Confluence</strong><b>↗</b></a>\n            <a href=\"/models/gpt-6-astra/\"><span>MENTIONED OPENAI MODEL</span><strong>GPT-6 Astra model reference</strong><b>↗</b></a>\n            <a href=\"/guides/model-context-protocol-mcp/\"><span>CONNECTION STANDARD</span><strong>How MCP connects agents to tools</strong><b>↗</b></a>\n            <a href=\"/guides/ai-agent-authorization/\"><span>ENTERPRISE CONTROLS</span><strong>Authorization and delegated access</strong><b>↗</b></a>\n            <a href=\"/topics/openai/\"><span>RELATED NEWS</span><strong>OpenAI signal archive</strong><b>↗</b></a>\n          </div>\n          <div class=\"intel-section-head\"><div><p class=\"eyebrow\">COMMON QUESTIONS</p><h2>Atlassian and OpenAI partnership FAQ.</h2></div></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>What did Atlassian and OpenAI announce on October 6, 2026?</strong> The companies expanded a partnership that began in 2023. OpenAI frontier models will support experiences across Atlassian's platform and Rovo, while Atlassian enterprise context can be used with supported ChatGPT and Codex integrations.</p></div>\n            <div><span>02</span><p><strong>What does the partnership change in Rovo?</strong> Atlassian can integrate evolving OpenAI models into Rovo while grounding their responses in its Teamwork Graph of projects, people, documents and decisions. This is intended to improve context-aware reasoning and actions.</p></div>\n            <div><span>03</span><p><strong>Can ChatGPT and Codex access Jira and Confluence?</strong> Supported Atlassian MCP and plugin integrations let authorized ChatGPT and Codex users work with permitted Jira and Confluence context. Exact capabilities depend on the client, connected apps and administrator settings.</p></div>\n            <div><span>04</span><p><strong>What is Atlassian's Teamwork Graph?</strong> It is Atlassian's enterprise context layer, connecting work items, documents, projects, people, decisions and relationships to give Rovo and connected AI systems better understanding of organizational work.</p></div>\n            <div><span>05</span><p><strong>Does the announcement mean AI agents can autonomously complete every Jira task now?</strong> No. The companies describe further agent assignment, tracking, synchronized work and review features as areas of exploration or development. The October 2026 partnership should not be read as a universal availability promise.</p></div>\n            <div><span>06</span><p><strong>Which OpenAI models are part of the deal?</strong> OpenAI says the expanded agreement includes access to frontier models such as GPT-6 Astra and the GPT-5.6 series. It does not say that every model is selectable in every Atlassian product or plan.</p></div>\n            <div><span>07</span><p><strong>How many Atlassian developers already use Codex?</strong> OpenAI and Atlassian reported that more than 3,000 Atlassian developers use Codex in terminal, editor or code review workflows. This is Atlassian's own adoption figure, not a quantified productivity gain.</p></div>\n            <div><span>08</span><p><strong>How is Atlassian MCP different from the Teamwork Graph CLI?</strong> Atlassian MCP exposes permitted Atlassian tools and context to supported AI clients via the Model Context Protocol. The Teamwork Graph CLI provides terminal-oriented access to the organization's connected work context; suitability depends on client and workflow.</p></div>\n            <div><span>09</span><p><strong>What should enterprises verify before enabling the integration?</strong> Confirm product and plan eligibility, OAuth scopes, data permissions, administrator approval, permitted write actions, review and audit trails, data retention terms, and how success will be measured before broad deployment.</p></div>\n            <div><span>10</span><p><strong>How can teams measure business value?</strong> Start with a controlled workflow such as launch-readiness reporting or ticket-to-code planning. Compare baseline versus assisted task completion time, accuracy of retrieved context, review effort and error rates; do not assume the partnership announcement proves ROI.</p></div>\n          </div>\n          <p><strong>Reporting note:</strong> “available now” describes only capabilities explicitly identified as current in the cited source materials. Recommendations about piloting, controls and measurement are SXF analysis. Deeper agent orchestration is discussed as future work; it is not presented as an already-shipped product.</p>\n        </section>\n"


def enrich_atlassian_openai_signal(page: str) -> str:
    if 'data-atlassian-openai-analysis' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("Atlassian/OpenAI signal canonical drift")
    page, count = re.subn(r'<title>.*?</title>', '<title>' + escape(TITLE) + '</title>', page, count=1)
    if count != 1:
        raise ValueError("Atlassian/OpenAI signal title missing")
    for name, value in [('description', DESCRIPTION), ('og:title', TITLE), ('og:description', DESCRIPTION), ('twitter:title', TITLE), ('twitter:description', DESCRIPTION)]:
        pattern = r'(<meta (?:name|property)="' + re.escape(name) + r'" content=")[^"]*(" />)'
        page, count = re.subn(pattern, lambda m: m.group(1) + escape(value, quote=True) + m.group(2), page, count=1)
        if count != 1:
            raise ValueError("Atlassian/OpenAI missing meta " + name)
    h1 = '<h1>Atlassian and OpenAI expand partnership to turn enterprise knowledge into action</h1>'
    if page.count(h1) != 1:
        raise ValueError("Atlassian/OpenAI H1 template drift")
    page = page.replace(h1, '<h1>Atlassian + OpenAI Partnership: Rovo, Jira, Codex and Enterprise AI</h1>', 1)
    page, count = re.subn(r'<p class="signal-summary">.*?</p>', lambda m: '<p class="signal-summary">' + escape(INTRO) + '</p>', page, count=1, flags=re.DOTALL)
    if count != 1:
        raise ValueError("Atlassian/OpenAI summary missing")
    updates = [
        (r'(<div class="signal-context"><span>WHY IT MATTERS</span><p>).*?(</p></div>)', 'The partnership links OpenAI reasoning to Atlassian\'s permission-aware records of work. That can improve the relevance of suggested next steps, provided sources are current and AI actions are governed. It does not guarantee higher productivity or unrestricted Jira automation.'),
        (r'(<div class="signal-context"><span>WHAT TO VERIFY</span><p>).*?(</p></div>)', 'Confirm which Rovo and ChatGPT/Codex connections are available to your plan, their OAuth scopes and write permissions, the freshness of Jira and Confluence records, human approval requirements and the status of future agent features.'),
    ]
    for pattern, answer in updates:
        page, count = re.subn(pattern, lambda m: m.group(1) + escape(answer) + m.group(2), page, count=1, flags=re.DOTALL)
        if count != 1:
            raise ValueError("Atlassian/OpenAI context block missing")
    marker = '        <section class="signal-taxonomy shell">'
    if page.count(marker) != 1:
        raise ValueError("Atlassian/OpenAI insertion marker changed")
    page = page.replace(marker, BODY + '\n' + marker, 1)
    page = page.replace('<div><span>MODELS</span><small>No named model detected</small></div>', '<div><span>MODELS</span><a href="/models/gpt-6-astra/">GPT-6 Astra</a></div>', 1)
    match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if match is None:
        raise ValueError("Atlassian/OpenAI JSON-LD missing")
    data = json.loads(match.group(2))
    if data.get('@context') != 'https://schema.org':
        raise ValueError("Atlassian/OpenAI unexpected structured data")
    graph = data['@graph']
    web = next(x for x in graph if x.get('@type') == 'WebPage')
    article = next(x for x in graph if x.get('@type') == 'Article')
    crumb = next(x for x in graph if x.get('@type') == 'BreadcrumbList')
    web['name'] = TITLE
    web['description'] = DESCRIPTION
    web['breadcrumb'] = {'@id': CANONICAL + '#breadcrumb'}
    article['@type'] = 'NewsArticle'
    article['headline'] = 'Atlassian + OpenAI Partnership: Rovo, Jira, Codex and Enterprise AI'
    article['description'] = DESCRIPTION
    article['dateModified'] = '2026-10-13'
    article['citation'] = SOURCES
    article['isBasedOn'] = SOURCES[0]
    article['keywords'] = ['Atlassian OpenAI partnership', 'Atlassian Rovo OpenAI', 'ChatGPT Jira Confluence', 'Codex Atlassian MCP', 'Teamwork Graph', 'GPT-6 Astra Atlassian', 'enterprise AI agents']
    article['about'] = [{'@type':'Organization','name':'Atlassian','url':'https://www.atlassian.com/'}, {'@type':'Organization','name':'OpenAI','url':'https://openai.com/'}, {'@type':'SoftwareApplication','name':'Atlassian Rovo'}, {'@type':'Thing','name':'Atlassian Teamwork Graph'}]
    crumb['itemListElement'].append({'@type':'ListItem','position':4,'name':'Atlassian + OpenAI partnership analysis','item':CANONICAL})
    graph.append({'@type':'FAQPage','@id':CANONICAL+'#faq','url':CANONICAL+'#atlassian-openai-deep-dive','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in FAQS]})
    encoded = json.dumps(data, ensure_ascii=False, separators=(',', ':'))
    page = page[:match.start(2)] + encoded + page[match.end(2):]
    return page
